import { test, expect, type Page } from '@playwright/test'
import {
  BUNDLE_SHA256,
  CANDIDATE_COMMIT,
  PATH_TOKEN,
  PRINT_REVIEWER_SESSION,
  REVIEWER_SESSION,
  REVIEW_DIFF,
  REVIEW_DIFF_ARTIFACT_ID,
  RUN_AWAITING,
  RUN_BLOCKED,
  RUN_LEGACY,
  RUN_SUCCEEDED,
  reviewFindings,
  sha256,
  uiPathQuote,
} from './fixtures.ts'
import { apiRun, attach, expectNoExecutionControls, fetchFromPage, graphNode, installHooks, nodeDetail, phase, renderedText, runUrl } from './support.ts'

installHooks()

const reviewPanel = (page: Page) => page.getByTestId('review-result')
const findings = (page: Page) => page.getByTestId('review-findings')
const findingRows = (page: Page) => findings(page).getByTestId('finding')
const group = (page: Page, disposition: string) => findings(page).locator(`section[data-disposition="${disposition}"]`)

test(`[scenario:review-verdict] The review node shows the verdict, reviewer, bundle, summary and findings (${phase})`, async ({ page }, testInfo) => {
  await page.goto(runUrl(RUN_SUCCEEDED, 'review'))
  await expect(nodeDetail(page)).toHaveAttribute('data-node-id', 'review')
  await expect(reviewPanel(page)).toBeVisible()
  await expect(page.getByTestId('result-none')).toHaveCount(0)

  // Verdict pill, reviewer identity with transport wording, and the node facts naming the same session.
  const verdict = page.getByTestId('review-verdict')
  await expect(verdict).toHaveText('Approved')
  await expect(verdict).toHaveClass(/status-succeeded/)
  const reviewer = page.getByTestId('review-reviewer')
  await expect(reviewer.locator('code')).toHaveText(REVIEWER_SESSION)
  await expect(reviewer).toContainText('native session')
  await expect(nodeDetail(page).locator('.projects-facts').first()).toContainText(REVIEWER_SESSION)

  // The bundle hash links to the candidate node the reviewer judged; the candidate commit is shown short.
  const bundle = page.getByTestId('review-bundle')
  await expect(bundle.locator('code').first()).toHaveText(BUNDLE_SHA256.slice(0, 12))
  await expect(bundle.locator('code').first()).toHaveAttribute('title', BUNDLE_SHA256)
  await expect(bundle.getByRole('link')).toHaveAttribute('href', runUrl(RUN_SUCCEEDED, 'candidate'))
  await expect(bundle).toContainText(CANDIDATE_COMMIT.slice(0, 12))

  // One-line summary and the findings table grouped by disposition (open before accepted, no resolved group).
  await expect(page.getByTestId('review-summary')).toHaveText('approved with 6 findings: 4 open, 2 accepted, none blocking')
  await expect(findingRows(page)).toHaveCount(6)
  await expect(group(page, 'open').getByRole('heading')).toContainText('Open')
  await expect(group(page, 'open').getByTestId('finding')).toHaveCount(4)
  await expect(group(page, 'accepted').getByTestId('finding')).toHaveCount(2)
  await expect(group(page, 'resolved')).toHaveCount(0)
  await expect(findings(page).locator('section')).toHaveCount(2)
  await expect(group(page, 'open').getByRole('columnheader')).toHaveText(['Severity', 'Message', 'Worker', 'Requirement'])
  for (const row of await findingRows(page).all()) {
    await expect(row).toHaveAttribute('data-severity', 'P2')
    await expect(row).not.toHaveClass(/finding-blocking/)
  }
  for (const finding of reviewFindings(RUN_SUCCEEDED)) await expect(findings(page)).toContainText(finding.message)
  await expect(findingRows(page).filter({ hasText: 'root Playwright suite' })).toHaveAttribute('data-worker', 'none')

  // The same findings can be grouped by the worker they concern (ui, adapter, both, none), keyboard-operable, then back.
  await expect(page.getByTestId('group-by-disposition')).toHaveAttribute('aria-pressed', 'true')
  await page.getByTestId('group-by-worker').click()
  await expect(findings(page)).toHaveAttribute('data-group-by', 'worker')
  await expect(findings(page).locator('section[data-worker-group]')).toHaveCount(4)
  await expect(findings(page).locator('section[data-worker-group="ui"]').getByTestId('finding')).toHaveCount(3)
  await expect(findings(page).locator('section[data-worker-group="none"]').getByRole('heading')).toContainText('No worker')
  await expect(findingRows(page)).toHaveCount(6)
  await page.getByTestId('group-by-disposition').click()
  await expect(group(page, 'open').getByTestId('finding')).toHaveCount(4)

  // The diff the reviewer saw is a plain-text patch artifact of this run, opened in a new tab.
  const diff = page.getByTestId('review-diff')
  const link = diff.getByRole('link')
  const artifactUrl = `${apiRun(RUN_SUCCEEDED)}/artifacts/${REVIEW_DIFF_ARTIFACT_ID}`
  await expect(link).toHaveAttribute('href', artifactUrl)
  await expect(link).toHaveAttribute('target', '_blank')
  await expect(link).toHaveAttribute('rel', /noopener/)
  await expect(diff).toContainText(sha256(REVIEW_DIFF).slice(0, 12))
  const served = await fetchFromPage(page, artifactUrl)
  expect(served.status).toBe(200)
  expect(served.contentType).toContain('text/plain')
  expect(served.text).toBe(REVIEW_DIFF)
  await expectNoExecutionControls(page)
  await attach(page, testInfo, 'review-verdict')

  // The bundle link navigates inside the run to the candidate node.
  await bundle.getByRole('link').click()
  await expect(page).toHaveURL(new RegExp(`${runUrl(RUN_SUCCEEDED, 'candidate')}$`))
  await expect(nodeDetail(page)).toHaveAttribute('data-node-id', 'candidate')
})

test(`[scenario:review-blocked] A blocked review shows the verdict, the failed node and the findings that caused it (${phase})`, async ({ page }, testInfo) => {
  await page.goto(runUrl(RUN_BLOCKED, 'review'))
  await expect(page.getByTestId('run-view')).toHaveAttribute('data-run-status', 'failed')
  await expect(page.getByTestId('run-status')).toContainText('Failed')
  await expect(nodeDetail(page)).toHaveAttribute('data-node-id', 'review')
  await expect(nodeDetail(page).locator('.status-badge').first()).toHaveText('Failed')
  await expect(page.getByTestId('node-status-meaning')).toContainText('This step failed')
  await expect(graphNode(page, 'review')).toHaveAttribute('data-status', 'failed')
  await expect(graphNode(page, 'approval')).toHaveAttribute('data-status', 'pending')
  await expect(graphNode(page, 'integrate')).toHaveAttribute('data-status', 'pending')

  const verdict = page.getByTestId('review-verdict')
  await expect(verdict).toHaveText('Blocked')
  await expect(verdict).toHaveClass(/status-failed/)
  const reviewer = page.getByTestId('review-reviewer')
  await expect(reviewer.locator('code')).toHaveText(PRINT_REVIEWER_SESSION)
  await expect(reviewer).toContainText('print-mode session')
  await expect(page.getByTestId('review-summary')).toHaveText('blocked with 2 findings: 1 open, 1 resolved, 1 blocking')

  // The unresolved P1 is marked as the blocking finding; the resolved P2 is listed but not blocking.
  await expect(findingRows(page)).toHaveCount(2)
  const blocking = group(page, 'open').getByTestId('finding')
  await expect(blocking).toHaveCount(1)
  await expect(blocking).toHaveAttribute('data-severity', 'P1')
  await expect(blocking).toHaveClass(/finding-blocking/)
  const resolved = group(page, 'resolved').getByTestId('finding')
  await expect(resolved).toHaveCount(1)
  await expect(resolved).toHaveAttribute('data-severity', 'P2')
  await expect(resolved).not.toHaveClass(/finding-blocking/)
  await expect(group(page, 'accepted')).toHaveCount(0)
  for (const finding of reviewFindings(RUN_BLOCKED)) await expect(findings(page)).toContainText(finding.message)
  await expect(page.getByTestId('review-diff')).toContainText('No diff artifact was recorded')
  await expect(page.getByTestId('projects-error')).toHaveCount(0)
  await expectNoExecutionControls(page)
  await attach(page, testInfo, 'review-blocked')
})

test(`[scenario:review-legacy] A run exported before review results says no review is recorded, without an error (${phase})`, async ({ page }, testInfo) => {
  await page.goto(runUrl(RUN_LEGACY, 'review'))
  await expect(page.getByTestId('run-view')).toHaveAttribute('data-run-status', 'succeeded')
  await expect(nodeDetail(page)).toHaveAttribute('data-node-id', 'review')
  await expect(nodeDetail(page).locator('.status-badge').first()).toHaveText('Succeeded')
  const none = page.getByTestId('review-none')
  await expect(none).toContainText('No review recorded for this run')
  await expect(none).toContainText('re-export')
  await expect(reviewPanel(page)).toHaveCount(0)
  await expect(page.getByTestId('projects-error')).toHaveCount(0)
  await expect(page.getByTestId('result-unscoped')).toHaveCount(0)
  await attach(page, testInfo, 'review-legacy')

  // A review that has not happened yet reads the same way: not recorded, not an error.
  await page.goto(runUrl(RUN_AWAITING, 'review'))
  await expect(page.getByTestId('awaiting-notice')).toBeVisible()
  await expect(page.getByTestId('review-none')).toBeVisible()
  await expect(reviewPanel(page)).toHaveCount(0)
  await expect(page.getByTestId('projects-error')).toHaveCount(0)
})

test(`[scenario:paths-redacted] No absolute path from the seeded review reaches the rendered panel (${phase})`, async ({ page }, testInfo) => {
  await page.goto(runUrl(RUN_SUCCEEDED, 'review'))
  await expect(findingRows(page)).toHaveCount(6)
  const text = await renderedText(reviewPanel(page))
  expect(text).toContain(PATH_TOKEN)
  await renderedText(nodeDetail(page))

  // The finding that names a directory carries the redaction marker in both its message and its quote.
  const row = findingRows(page).filter({ hasText: 'Screenshots were written beside' })
  await expect(row).toContainText(`beside ${PATH_TOKEN} instead of below it.`)
  await expect(row.getByTestId('finding-requirement')).toHaveText(uiPathQuote(PATH_TOKEN))
  await attach(page, testInfo, 'paths-redacted')
})
==== HARNESS
/**
 * Shared knowledge between the suite's Playwright config, teardown and specs: the verification phase,
 * the temporary root layout and the port variables. Kept free of side effects so importing it is safe in
 * every Playwright process (the config module is evaluated in the runner and in each worker).
 */
export const ROOT_PREFIX = 'md-manager-projects-e2e-'

export type Phase = 'worker' | 'candidate'

/** `worker`: no projects backend, mock only /api/projects/**. `candidate`: real combined backend, no success mocks. */
export function verificationPhase(env: NodeJS.ProcessEnv = process.env): Phase {
  const value = env.WORKFLOW_VERIFICATION_PHASE
  if (value === 'candidate') return 'candidate'
  if (value === 'worker' || value === undefined || value === '') return 'worker'
  throw new Error(`Unsupported WORKFLOW_VERIFICATION_PHASE "${value}": expected "worker" or "candidate".`)
}

/** Skills fixture locations mirrored from the root harness so the existing Pi/Claude helpers keep working. */
export const SKILL_LOCATIONS = [
  { id: 'pi-personal', source: 'Pi', label: 'Personal skills', directory: 'pi-personal', category: 'personal' },
  { id: 'pi-package', source: 'Pi', label: 'Package: demo', directory: 'pi-package', category: 'package' },
  { id: 'pi-missing', source: 'Pi', label: 'Project: gone', directory: 'pi-missing', category: 'project' },
  { id: 'claude-personal', source: 'Claude', label: 'Personal and synced skills', directory: 'claude-personal', category: 'personal' },
  { id: 'claude-plugin', source: 'Claude', label: 'Plugin: design', directory: 'claude-plugin', category: 'plugin' },
] as const
==== MOCK
/**
 * Worker-phase mocks for the not-yet-present projects backend. Only `/api/projects` and its nested routes
 * are intercepted; every other request (Pi/Claude listing, documents, mutations) reaches the real isolated
 * API. Responses are the explicit contract fixtures from `fixtures.ts`, plus contract-shaped 404s. Review
 * results and run inputs answer with the contract's `REVIEW_NOT_FOUND` / `INPUTS_NOT_FOUND` codes when a
 * run has none, exactly like the real adapter for exports that predate those sections.
 */
import type { Page, Route } from '@playwright/test'
import { artifactFiles, PROJECT, projectList, reviewResults, runDetails, runEvents, runInputs, runLists, workerResults, workflowLists } from './fixtures.ts'

const json = (body: unknown, status = 200) => ({ status, contentType: 'application/json', body: JSON.stringify(body) })
const notFound = (message: string, code = 'not_found') => json({ error: { code, message } }, 404)

export function isProjectsRequest(url: URL): boolean {
  return url.pathname === '/api/projects' || url.pathname.startsWith('/api/projects/')
}

/** Resolves one mocked projects API request; returns null for unknown paths under the prefix (404). */
export function mockResponse(url: URL): { status: number; contentType: string; body: string | Buffer } {
  const segments = url.pathname.split('/').filter(Boolean).slice(2).map(decodeURIComponent) // after /api/projects
  if (segments.length === 0) return json(projectList)
  const [projectId, workflowsLiteral, workflowId, runsLiteral, runId, ...rest] = segments
  const workflows = workflowLists[projectId]
  if (!workflows) return notFound(`Project "${projectId}" is not registered.`)
  if (workflowsLiteral !== 'workflows') return notFound('Unknown resource.')
  if (workflowId === undefined) return json(workflows)
  if (!workflows.workflows.some(workflow => workflow.workflow_id === workflowId)) return notFound(`Workflow "${workflowId}" does not belong to project "${projectId}".`)
  if (runsLiteral !== 'runs') return notFound('Unknown resource.')
  if (runId === undefined) {
    // Runs are listed per workflow (empty-flow and any other registered workflow without runs answer an empty page).
    return json(projectId === PROJECT.project_id ? runLists[workflowId] ?? { runs: [], next_cursor: null } : { runs: [], next_cursor: null })
  }
  const candidate = projectId === PROJECT.project_id ? runDetails[runId] : undefined
  const detail = candidate && candidate.summary.workflow_id === workflowId ? candidate : undefined
  if (!detail) return notFound(`Run "${runId}" was not found in workflow "${workflowId}".`)
  if (rest.length === 0) return json(detail)
  const [kind, ...tail] = rest
  if (kind === 'events' && tail.length === 0) {
    const after = Number(url.searchParams.get('after') ?? '0')
    return json({ events: runEvents[runId].filter(event => event.sequence > after) })
  }
  if (kind === 'results' && tail.length === 2) {
    const result = workerResults[runId][`${tail[0]}/${tail[1]}`]
    return result ? json(result) : notFound(`No result for ${tail[0]} attempt ${tail[1]}.`)
  }
  if (kind === 'reviews' && tail.length === 1) {
    const review = reviewResults[runId]
    return review && tail[0] === String(review.attempt)
      ? json(review)
      : notFound('No review is recorded for that attempt: either the review has not happened or the run export predates review results.', 'REVIEW_NOT_FOUND')
  }
  if (kind === 'inputs' && tail.length === 0) {
    const inputs = runInputs[runId]
    return inputs ? json(inputs) : notFound('No inputs are recorded for this run: its export predates run inputs.', 'INPUTS_NOT_FOUND')
  }
  if (kind === 'artifacts' && tail.length === 1) {
    const artifact = artifactFiles[runId].find(file => file.artifact_id === tail[0])
    return artifact ? { status: 200, contentType: artifact.contentType, body: artifact.content } : notFound(`Artifact "${tail[0]}" is not registered for this run.`)
  }
  return notFound('Unknown resource.')
}

export async function installProjectMocks(page: Page): Promise<void> {
  await page.route(url => isProjectsRequest(url), async (route: Route) => {
    const request = route.request()
    if (request.method() !== 'GET') {
      await route.fulfill(json({ error: { code: 'method_not_allowed', message: 'This surface is read-only.' } }, 405))
      return
    }
    await route.fulfill(mockResponse(new URL(request.url())))
  })
}
==== SUPPORT
/**
 * Helpers shared by the Projects viewer specs: URL builders, locators for the run view, the screenshot
 * attachment every scenario records, the per-test setup (isolated API up, mocks in worker mode) and the
 * redaction assertion used by the `paths-redacted` scenarios.
 */
import { test, expect, type APIRequestContext, type Locator, type Page, type TestInfo } from '@playwright/test'
import { waitForApi } from '../helpers.ts'
import { apiRunPath, PROJECT, WORKFLOW_ID } from './fixtures.ts'
import { verificationPhase } from './harness.ts'
import { installProjectMocks } from './mock.ts'

export const phase = verificationPhase()

export const projectsUrl = '/projects'
export const projectUrl = (projectId: string) => `/projects/${encodeURIComponent(projectId)}`
export const workflowUrl = (projectId: string, workflowId: string) => `${projectUrl(projectId)}/workflows/${encodeURIComponent(workflowId)}`
export const runUrl = (runId: string, nodeId?: string, workflowId: string = WORKFLOW_ID) => `${workflowUrl(PROJECT.project_id, workflowId)}/runs/${encodeURIComponent(runId)}${nodeId ? `/nodes/${encodeURIComponent(nodeId)}` : ''}`
export const apiRun = apiRunPath

export const workspace = (page: Page) => page.getByTestId('projects-workspace')
export const graphNode = (page: Page, nodeId: string) => page.locator(`[data-testid="workflow-graph"] [data-graph-node="${nodeId}"]`)
export const nodeListItem = (page: Page, nodeId: string) => page.locator(`[data-testid="run-node-list"] [data-node-id="${nodeId}"]`)
export const nodeDetail = (page: Page) => page.getByTestId('node-detail')

/** No view action may launch, approve, retry, delete or edit a run: no such real controls exist (graph nodes are read-only selectors). */
export async function expectNoExecutionControls(page: Page) {
  const controls = workspace(page).locator('button, input, select, textarea, [role="menuitem"]')
  await expect(controls.filter({ hasText: /approve|retry|launch|start|resume|delete|cancel|integrate|edit|save/i })).toHaveCount(0)
  await expect(page.locator('form')).toHaveCount(0)
}

export async function attach(page: Page, testInfo: TestInfo, id: string) {
  const image = testInfo.outputPath(`${id}.png`)
  await page.screenshot({ path: image, fullPage: true })
  await testInfo.attach(`screenshot:${id}`, { path: image, contentType: 'image/png' })
}

export async function waitForProjectsApi(request: APIRequestContext) {
  if (phase !== 'candidate') return
  await expect.poll(async () => (await request.get('/api/projects')).status(), { timeout: 30_000 }).toBe(200)
}

/** Registers the suite's shared per-test setup; call once at the top level of a spec file. */
export function installHooks() {
  test.beforeEach(async ({ page, request }) => {
    await waitForApi(request)
    await waitForProjectsApi(request)
    if (phase === 'worker') await installProjectMocks(page)
  })
}

/** Reads the rendered text and asserts no absolute filesystem path (temporary root or home) leaked into it. */
export async function renderedText(locator: Locator): Promise<string> {
  const text = await locator.innerText()
  expect(text, 'rendered text must not name a temporary or home directory').not.toMatch(/\/tmp\/|\/home\//)
  return text
}

/** Fetches a URL from inside the page, so worker-mode route mocks apply exactly as they do for the app. */
export async function fetchFromPage(page: Page, url: string): Promise<{ status: number; contentType: string | null; text: string }> {
  return page.evaluate(async target => {
    const response = await fetch(target)
    return { status: response.status, contentType: response.headers.get('content-type'), text: await response.text() }
  }, url)
}
==== CONFIG
import { defineConfig } from '@playwright/test'
import { execFileSync } from 'node:child_process'
import { cpSync, mkdirSync, mkdtempSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { ROOT_PREFIX, SKILL_LOCATIONS, verificationPhase } from './harness.ts'
import { seedCandidate } from './seed.ts'

/**
 * Dedicated configuration for the Projects viewer scenarios (`features/project-workflows/policy.json`).
 *
 * - Its own temporary root (skills fixtures for Pi/Claude and, in candidate mode, the seeded project
 *   registry and run directories) and its own dynamically chosen API/web ports, so it never touches live
 *   skills, live project storage or a developer's running servers. `global-teardown.ts` removes the root.
 * - `WORKFLOW_VERIFICATION_PHASE=worker` (default): the backend has no projects routes; specs mock only
 *   `/api/projects/**` with the explicit contract fixtures.
 * - `WORKFLOW_VERIFICATION_PHASE=candidate`: the real combined backend is started with the seeded registry;
 *   no project success responses are mocked.
 *
 * Playwright evaluates this module in the runner and again in every worker process; the root and ports are
 * prepared once and handed down through the environment.
 */
const phase = verificationPhase()

function freePort(): number {
  const script = "const s=require('net').createServer();s.listen(0,'127.0.0.1',()=>{process.stdout.write(String(s.address().port));s.close()})"
  return Number(execFileSync(process.execPath, ['-e', script], { encoding: 'utf8' }).trim())
}

function prepare(): { root: string; apiPort: number; webPort: number; projectsConfig: string | null } {
  const existing = process.env.MD_MANAGER_PROJECTS_TEST_ROOT
  if (existing) {
    return {
      root: existing,
      apiPort: Number(process.env.MD_MANAGER_API_PORT),
      webPort: Number(process.env.MD_MANAGER_WEB_PORT),
      projectsConfig: process.env.MD_MANAGER_PROJECTS_CONFIG || null,
    }
  }
  const root = mkdtempSync(join(tmpdir(), ROOT_PREFIX))
  const fixtures = fileURLToPath(new URL('../../fixtures/', import.meta.url))
  cpSync(join(fixtures, 'pi'), join(root, 'pi-personal'), { recursive: true })
  cpSync(join(fixtures, 'claude'), join(root, 'claude-personal'), { recursive: true })
  mkdirSync(join(root, 'pi-package', 'review'), { recursive: true })
  writeFileSync(join(root, 'pi-package', 'review', 'SKILL.md'), '# Package review skill\n\nInstalled by a package.\n')
  mkdirSync(join(root, 'claude-plugin', 'review'), { recursive: true })
  writeFileSync(join(root, 'claude-plugin', 'review', 'SKILL.md'), '# Plugin review skill\n\nInstalled by a plugin.\n')
  // pi-missing is configured but deliberately not created: an unavailable location, as in the root harness.
  const sources = { version: 1, locations: SKILL_LOCATIONS.map(({ id, source, label, directory, category }) => ({ id, source, label, path: join(root, directory), category })) }
  writeFileSync(join(root, 'sources.json'), `${JSON.stringify(sources, null, 2)}\n`)
  const projectsConfig = phase === 'candidate' ? seedCandidate(join(root, 'projects')) : null
  let apiPort = freePort()
  let webPort = freePort()
  while (webPort === apiPort) webPort = freePort()
  if (apiPort === webPort) apiPort = freePort()
  process.env.MD_MANAGER_PROJECTS_TEST_ROOT = root
  // The root skills helpers read this to locate the seeded location directories.
  process.env.MD_MANAGER_TEST_ROOT = root
  process.env.MD_MANAGER_CONFIG = join(root, 'sources.json')
  process.env.MD_MANAGER_API_PORT = String(apiPort)
  process.env.MD_MANAGER_WEB_PORT = String(webPort)
  process.env.WORKFLOW_VERIFICATION_PHASE = phase
  if (projectsConfig) process.env.MD_MANAGER_PROJECTS_CONFIG = projectsConfig
  else delete process.env.MD_MANAGER_PROJECTS_CONFIG
  return { root, apiPort, webPort, projectsConfig }
}

const { root, apiPort, webPort, projectsConfig } = prepare()
const baseURL = `http://127.0.0.1:${webPort}`

const apiEnv: Record<string, string> = {
  MD_MANAGER_CONFIG: join(root, 'sources.json'),
  MD_MANAGER_FIXTURE_ROOT: '',
  MD_MANAGER_API_PORT: String(apiPort),
  MD_MANAGER_WEB_PORT: String(webPort),
  WORKFLOW_VERIFICATION_PHASE: phase,
  ...(projectsConfig ? { MD_MANAGER_PROJECTS_CONFIG: projectsConfig } : {}),
}

export default defineConfig({
  testDir: '.',
  testMatch: '**/*.spec.ts',
  globalTeardown: './global-teardown.ts',
  outputDir: process.env.MD_MANAGER_PROJECTS_OUTPUT ?? join(process.cwd(), 'test-results', 'project-workflows'),
  workers: 1,
  fullyParallel: false,
  retries: 0,
  use: {
    baseURL,
    browserName: 'chromium',
    reducedMotion: 'reduce',
  },
  webServer: [
    {
      command: 'npm run start:api',
      url: `http://127.0.0.1:${apiPort}/api/entries`,
      env: apiEnv,
      reuseExistingServer: false,
      timeout: 30_000,
    },
    {
      command: 'npm run dev:web',
      url: baseURL,
      env: { MD_MANAGER_API_PORT: String(apiPort), MD_MANAGER_WEB_PORT: String(webPort) },
      reuseExistingServer: false,
      timeout: 30_000,
    },
  ],
})
==== TEARDOWN
import { rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, sep } from 'node:path'
import { ROOT_PREFIX } from './harness.ts'

/** Removes the temporary root created by this suite's playwright.config.ts, whatever the outcome. */
export default async function globalTeardown() {
  const root = process.env.MD_MANAGER_PROJECTS_TEST_ROOT
  // Only ever delete a directory this harness created inside the OS temp directory.
  if (root && root.startsWith(join(tmpdir(), ROOT_PREFIX)) && !root.endsWith(sep)) {
    rmSync(root, { recursive: true, force: true })
  }
}

