import { isBlockingFinding, type ReviewFinding, type ReviewResult } from './api.ts'

export type Reviewer = ReviewResult['reviewers'][number]
export type ReviewerStatus = Reviewer['status']

const SEVERITIES: readonly ReviewFinding['severity'][] = ['P0', 'P1', 'P2']

/** How each reviewer ended, as the controller recorded it. */
export const REVIEWER_STATUS_WORDING: Record<ReviewerStatus, string> = {
  accepted: 'completion file accepted',
  blocked: 'blocked the candidate',
  rejected: 'completion file rejected',
  timed_out: 'reached the review deadline without a verdict',
  superseded: 'stopped after the combined decision, no verdict',
}

/** Statuses that block the run on their own; `superseded` is the consequence of another reviewer's block, not a cause. */
const BLOCKING_STATUSES: readonly ReviewerStatus[] = ['blocked', 'rejected', 'timed_out']

/** "1 P1, 2 P2" in severity order, listing only the severities present; "no findings" when the list is empty. */
export function severityCounts(findings: readonly Pick<ReviewFinding, 'severity'>[]): string {
  if (findings.length === 0) return 'no findings'
  return SEVERITIES
    .map(severity => [severity, findings.filter(finding => finding.severity === severity).length] as const)
    .filter(([, count]) => count > 0)
    .map(([severity, count]) => `${count} ${severity}`)
    .join(', ')
}

function list(items: readonly string[]): string {
  if (items.length <= 1) return items.join('')
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`
}

/**
 * Why a blocked review is blocked, naming the reviewers: those whose own outcome blocked (a blocked verdict, a rejected
 * file, the deadline), else those that approved but left an unresolved P0/P1, then the reviewers stopped because of it.
 * Null for an approved review.
 */
export function blockedByWording(review: Pick<ReviewResult, 'verdict' | 'reviewers'>): string | null {
  if (review.verdict !== 'blocked') return null
  const blockers = review.reviewers.filter(reviewer => BLOCKING_STATUSES.includes(reviewer.status))
    .map(reviewer => `${reviewer.reviewer_id} ${REVIEWER_STATUS_WORDING[reviewer.status]}`)
  const unresolved = review.reviewers.filter(reviewer => !BLOCKING_STATUSES.includes(reviewer.status) && reviewer.findings.some(isBlockingFinding))
    .map(reviewer => `${reviewer.reviewer_id} left an unresolved P0/P1 finding`)
  const reasons = [...blockers, ...unresolved]
  const superseded = review.reviewers.filter(reviewer => reviewer.status === 'superseded').map(reviewer => reviewer.reviewer_id)
  const head = reasons.length === 0
    ? 'Blocked: the combined verdict is blocked although no reviewer recorded a blocking outcome.'
    : `Blocked by ${list(reasons)}.`
  const tail = superseded.length === 0 ? '' : ` ${list(superseded)} ${superseded.length === 1 ? 'was' : 'were'} superseded: stopped after that decision, no verdict recorded.`
  return head + tail
}
